 private static final class Job<T> extends FutureTask<T> {final long bytes;boolean freed,abandoned;Job(long bytes,Callable<T> work){super(work);this.bytes=bytes;}private synchronized void free(){if(!freed){freed=true;synchronized(NativeRampJournal.class){queued-=bytes;}}}T consume()throws Exception{try{return get();}finally{free();}}synchronized void abandon(){abandoned=true;if(isDone())free();}@Override protected synchronized void done(){if(abandoned)free();}}
 private static synchronized <T> Job<T> submit(long weight,java.util.function.Supplier<Callable<T>> factory){if(weight<0||queued+weight>IO_BYTES)return null;queued+=weight;try{var job=new Job<T>(weight,factory.get());IO.execute(job);return job;}catch(RejectedExecutionException busy){queued-=weight;return null;}catch(RuntimeException|Error failed){queued-=weight;throw failed;}}

 private static CompoundTag read(Path file)throws IOException {if(Files.size(file)>FILE_BYTES)throw new IOException("Ramp journal file limit");var tag=NbtIo.readCompressed(file,NbtAccounter.create(NBT_BYTES));if(!tag.contains("NativeRampJournalSchema",Tag.TAG_INT)||!Set.of(1,2,3).contains(tag.getInt("NativeRampJournalSchema"))||!tag.hasUUID("Operation")||!tag.hasUUID("Actor")||!(tag.getInt("NativeRampJournalSchema")==1?Set.of("PREPARED","ARMED"):Set.of("PREPARED","ARMED","APPLIED","RESTORING")).contains(tag.getString("Stage")))throw new IOException("Unsupported Ramp journal retained: "+file.getFileName());if(!file.getFileName().toString().equals(tag.getUUID("Operation")+".nbt"))throw new IOException("Ramp journal filename identity mismatch");for(String key:new String[]{"RootX","RootY","RootZ"})if(!tag.contains(key,Tag.TAG_INT))throw new IOException("Unknown Ramp root coordinate schema");if(!tag.contains("Before",Tag.TAG_LIST)||!tag.contains("Proxy",Tag.TAG_COMPOUND)||!tag.contains("Dimension",Tag.TAG_STRING))throw new IOException("Unknown Ramp record fields");return tag;}
 private static void directories(Path directory)throws IOException {var missing=new ArrayDeque<Path>();for(var p=directory.toAbsolutePath();!Files.isDirectory(p);p=p.getParent()){if(p==null||Files.exists(p))throw new IOException("Ramp journal parent is not a directory");missing.push(p);}while(!missing.isEmpty()){var next=missing.pop();Files.createDirectory(next);JournalFiles.syncDirectory(next.getParent());}}
