 private static BlockState decode(ServerLevel level,CompoundTag tag){var id=net.minecraft.resources.ResourceLocation.tryParse(tag.getString("Name"));if(id==null||!BuiltInRegistries.BLOCK.containsKey(id))throw new IllegalArgumentException("Unknown journal block");var state=NbtUtils.readBlockState(level.holderLookup(Registries.BLOCK),tag);if(!NbtUtils.writeBlockState(state).equals(tag))throw new IllegalArgumentException("Unknown journal block properties");return state;}
