 private static void add(State state,Operation op){state.operations.put(op.id,op);state.locks.put(op.root,op.id);for(var pos:exclusivePositions(op))state.locks.put(pos,op.id);state.weight+=op.weight;retained+=op.weight;}
 public static boolean publishingInArea(ServerLevel level,net.minecraft.world.phys.AABB area){thread(level);var state=WORLDS.get(level);if(state==null)return false;for(var op:state.operations.values())if(NativeRampHeldOwners.held(op)&&op.phase!=Phase.APPLIED&&op.phase!=Phase.DONE&&op.bounds.intersects(area))return true;return false;}
